def squares(n) {
    return [i * i for i to n if i % 2 == 1]
}
def count_big(xs, t) {
    return len([x for x in xs if x > t])
}
print(squares(8), count_big([5, 1, 7], 4))

def say(x) {
    print("say", x)
    return x
}
v = say(1) + sum([say(x) for x in [2, 3]])
print(v)

def big(x) {
    print("saw", x)
    return x > 1
}
print(all(big(x) for x in [2, 0, 5]))
print(any(big(x) for x in [0, 3, 7]))

