def pivot(col, k) {
    return max([i for i from k to len(col)], key=fn(i) -> abs(col[i]))
}
def by_len(words) {
    return sorted(words, key=len)
}
print(pivot([1, -7, 3, 7], 0), pivot([1, -7, 3, 7], 2), by_len(split("ccc a bb")))

